import React, { useState, useEffect, useRef } from 'react';
import gsap from 'gsap';
import { pinApi, BASE_URL } from '../utils/api';

const LandingPage = () => {
  const [heroImages, setHeroImages] = useState([]);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const leftImagesRef = useRef({});
  const rightImagesRef = useRef({});
  const heroTextRef = useRef(null);
  const dotsRef = useRef(null);

  // Fetch images from admin uploads
  useEffect(() => {
    const fetchHeroImages = async () => {
      try {
        console.log('Fetching pins from API...');
        const pins = await pinApi.getPins();
        console.log('API response:', pins);
        
        // Filter for hero-worthy images (you can adjust criteria)
        const heroPins = pins.filter(pin => 
          pin.image && 
          (pin.title?.length > 0 || pin.description?.length > 0)
        ).slice(0, 12); // Limit to 12 images for the hero section
        
        console.log('Filtered heroPins:', heroPins);
        setHeroImages(heroPins);
      } catch (error) {
        console.error('Error fetching hero images:', error);
      }
    };

    fetchHeroImages();
  }, []);

  // Auto-rotate images every 4 seconds
  useEffect(() => {
    if (heroImages.length === 0) return;

    const interval = setInterval(() => {
      setCurrentImageIndex(prev => (prev + 1) % heroImages.length);
    }, 4000);

    return () => clearInterval(interval);
  }, [heroImages.length]);

  // Split images for left and right columns
  const leftImages = heroImages.filter((_, index) => index % 2 === 0).slice(0, 6);
  const rightImages = heroImages.filter((_, index) => index % 2 === 1).slice(0, 6);

  // Animate images when they change
  useEffect(() => {
    if (heroImages.length === 0) return;

    // Animate left images
    leftImages.forEach((pin) => {
      const imgRef = leftImagesRef.current[pin.id];
      if (imgRef) {
        const index = leftImages.findIndex(p => p.id === pin.id);
        gsap.to(imgRef, {
          opacity: index === currentImageIndex % 6 ? 1 : 0.7,
          scale: index === currentImageIndex % 6 ? 1.05 : 1,
          duration: 0.8,
          ease: "power2.out"
        });
      }
    });

    // Animate right images
    rightImages.forEach((pin) => {
      const imgRef = rightImagesRef.current[pin.id];
      if (imgRef) {
        const index = rightImages.findIndex(p => p.id === pin.id);
        gsap.to(imgRef, {
          opacity: index === currentImageIndex % 6 ? 1 : 0.7,
          scale: index === currentImageIndex % 6 ? 1.05 : 1,
          duration: 0.8,
          ease: "power2.out"
        });
      }
    });
  }, [currentImageIndex, leftImages, rightImages]); // Fixed dependency

  // Initial page load animations
  useEffect(() => {
    // Hero text animation
    if (heroTextRef.current) {
      // Animate the Creative Stock logo letters with multiple creative effects
      const logoSpans = heroTextRef.current.querySelectorAll('.creative-stock-logo');
      
      // Create staggered animation for each letter
      logoSpans.forEach((span, index) => {
        // Split each word into individual characters for character-by-character animation
        const textContent = span.textContent;
        span.innerHTML = '';
        
        // Create a container for each character
        textContent.split('').forEach((char, charIndex) => {
          const charSpan = document.createElement('span');
          charSpan.textContent = char;
          charSpan.style.display = 'inline-block';
          charSpan.style.margin = '0 2px';
          span.appendChild(charSpan);
          
          // Apply multiple animation effects
          gsap.fromTo(charSpan,
            { 
              opacity: 0, 
              y: index === 0 ? -100 : 100, 
              scale: 0, 
              rotationX: 180,
              rotationY: index === 0 ? -180 : 180
            },
            { 
              opacity: 1, 
              y: 0, 
              scale: 1, 
              rotationX: 0,
              rotationY: 0,
              duration: 1.2, 
              delay: 0.1 * (index * textContent.length + charIndex), 
              ease: "elastic.out(1.2, 0.6)",
              // Additional animation after the initial one
              onComplete: () => {
                // Add a subtle continuous animation
                gsap.to(charSpan, {
                  y: -5,
                  duration: 1,
                  yoyo: true,
                  repeat: -1,
                  ease: "sine.inOut",
                  delay: 0.5
                });
              }
            }
          );
          
          // Add a secondary glow effect
          gsap.fromTo(charSpan,
            { boxShadow: "0 0 0px #ff0000" },
            { 
              boxShadow: index === 0 ? "0 0 5px #666" : "0 0 5px #f00",
              duration: 1.5,
              delay: 0.1 * (index * textContent.length + charIndex) + 0.5,
              repeat: -1,
              yoyo: true,
              ease: "power1.inOut"
            }
          );
        });
      });
      
      // Add overall container animation
      gsap.fromTo(heroTextRef.current,
        { scale: 0.5, rotation: -5 },
        { scale: 1, rotation: 0, duration: 1.5, ease: "elastic.out(1, 0.5)" }
      );
    }

    // Slider dots animation
    if (dotsRef.current) {
      gsap.fromTo(dotsRef.current,
        { opacity: 0, y: 20 },
        { opacity: 1, y: 0, duration: 1, delay: 0.3, ease: "power3.out" }
      );
    }

    // Grid images initial animation
    setTimeout(() => {
      heroImages.forEach((pin, index) => {
        const imgRef = leftImagesRef.current[pin.id];
        if (imgRef) {
          gsap.fromTo(imgRef,
            { opacity: 0, y: 30, scale: 0.9 },
            { opacity: 0.9, y: 0, scale: 1, duration: 0.8, delay: index * 0.05, ease: "back.out(1.2)" }
          );
        }
      });
    }, 500);
  }, [heroImages]);

  const imageUrl = (pin) => pin.image?.startsWith('http') ? pin.image : `${BASE_URL}${pin.image || ''}`;

  return (
    <div className="min-h-screen pb-16 bg-white">
      {/* Fixed Creative Stock logo strip – stays below main header, does not scroll */}
      <div className="fixed top-14 left-0 right-0 z-40 h-32 bg-white border-b border-gray-100 shadow-sm flex flex-col items-center justify-center">
        <div ref={heroTextRef} className="text-center">
          <h1 className="text-4xl md:text-5xl lg:text-6xl font-bold leading-tight">
            <span className="block text-gray-900 creative-stock-logo" style={{ fontFamily: "'Arial Black', 'Arial Bold', Gadget, sans-serif" }}>Creative</span>
            <span className="block text-red-600 creative-stock-logo" style={{ fontFamily: "'Arial Black', 'Arial Bold', Gadget, sans-serif" }}>Stock</span>
          </h1>
        </div>
        <div ref={dotsRef} className="flex space-x-2 mt-2">
          {[...Array(3)].map((_, index) => (
            <div
              key={index}
              className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${
                index === currentImageIndex % 3 ? 'bg-red-600 scale-125' : 'bg-gray-300'
              }`}
            />
          ))}
        </div>
      </div>

      {/* Scrollable content: images centered below the fixed logo */}
      <div className="pt-32 container mx-auto px-4">
        {/* Centered image grid – all hero images below Creative Stock logo */}
        <div className="max-w-5xl mx-auto grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
          {heroImages.map((pin) => (
            <div
              key={pin.id}
              ref={el => {
                if (el) {
                  leftImagesRef.current[pin.id] = el;
                  rightImagesRef.current[pin.id] = el;
                } else {
                  delete leftImagesRef.current[pin.id];
                  delete rightImagesRef.current[pin.id];
                }
              }}
              className="relative group overflow-hidden rounded-2xl"
              style={{ paddingBottom: '120%' }}
            >
              <img
                src={imageUrl(pin)}
                alt={pin.title || 'Creative inspiration'}
                className="absolute inset-0 w-full h-full object-cover transition-all duration-700"
                onError={(e) => { e.target.style.display = 'none'; }}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-white/60 via-transparent to-transparent" />
              <div className="absolute inset-0 bg-black/20 opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default LandingPage;
